# Builds wv-truck-parking-dashboard.html from wv-truck-parking-master.csv.
# Interactive dashboard: Leaflet map (streets + Esri satellite), facility list,
# filters, live charts, per-facility detail modal with local satellite imagery
# and a TruckStopsAndServices.com source tab (from wv-truck-parking-tss.csv,
# generated by tools\fetch-tss.ps1), printable report generation, and filtered
# CSV export.
# Rerun after any master CSV or TSS CSV edit:
#   powershell -ExecutionPolicy Bypass -File tools\build-dashboard.ps1
# Requires internet in the browser for map tiles + Leaflet CDN; everything else is local.

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$csvPath = Join-Path $root 'wv-truck-parking-master.csv'
$outPath = Join-Path $root 'wv-truck-parking-dashboard.html'
$rows = Import-Csv $csvPath

# capacity table + classification helpers shared with build-summary-pdf.ps1
. (Join-Path $PSScriptRoot 'facility-classify.ps1')

# toll facility + traffic layer manifest/loader (see tools\traffic-data.ps1)
. (Join-Path $PSScriptRoot 'traffic-data.ps1')

# truckstopsandservices.com source data (see tools\fetch-tss.ps1); optional
$tssPath = Join-Path $root 'wv-truck-parking-tss.csv'
$tssByName = @{}
$tssDate = ''
if (Test-Path $tssPath) {
  foreach ($t in Import-Csv $tssPath) {
    $tssByName[$t.MasterName] = $t
    if ($t.FetchedDate -gt $tssDate) { $tssDate = $t.FetchedDate }
  }
}

$headers = $rows[0].psobject.Properties.Name
$i = 0
$list = foreach ($r in $rows) {
  $e = $cap[$r.Name]
  if ($null -eq $e) { throw "No capacity entry for: $($r.Name)" }
  $lat = $null; $lon = $null
  if ($r.Latitude -match '\d') { $lat = [double]$r.Latitude }
  if ($r.Longitude -match '\d') { $lon = [double]$r.Longitude }
  $sat = $r.'Satellite image'
  if ($sat -and -not (Test-Path (Join-Path $root "satellite\$sat"))) { $sat = '' }
  $raw = [ordered]@{}
  foreach ($h in $headers) { $raw[$h] = $r.$h }
  [pscustomobject]@{
    id = $i; name = $r.Name
    corr = Get-CorridorGroup $r.Corridor
    type = Get-TypeGroup $r.'Facility type'
    own = Get-OwnerShort $r.Ownership
    status = Get-StatusShort $r.Status
    conf = $r.Confidence
    lat = $lat; lon = $lon
    capMid = $e.mid; capClass = $e.class
    sat = $sat
    raw = $raw
    tss = $(if ($tssByName.ContainsKey($r.Name)) {
      $t = $tssByName[$r.Name]
      $o = [ordered]@{}
      foreach ($p in $t.PSObject.Properties) { if ($p.Name -ne 'MasterName') { $o[$p.Name] = $p.Value } }
      $o
    } else { $null })
  }
  $i++
}
$json = ConvertTo-Json -InputObject @($list) -Depth 6 -Compress
$colsJson = ConvertTo-Json -InputObject @($headers) -Compress
$today = Get-Date -Format 'MMMM d, yyyy'

# toll + traffic data layers (see tools\traffic-data.ps1); each layer's
# hasData flag is computed from actual traffic-data\*.csv row counts.
$traffic = Get-TrafficLayers -Root $root
$trafficJson = ConvertTo-Json -InputObject $traffic.Layers -Depth 6 -Compress
$trafficMetaJson = ConvertTo-Json -InputObject @($traffic.Meta) -Depth 4 -Compress
$trafficLibJs = Get-Content (Join-Path $PSScriptRoot 'traffic-lib.js') -Raw

$tpl = @'
<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>WV Truck Parking Dashboard</title>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css">
<link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.Default.css">
<script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script>
<style>
:root {
  --bg:#f9f9f7; --surface:#fcfcfb; --ink:#0b0b0b; --ink2:#52514e; --muted:#898781;
  --grid:#e1e0d9; --border:rgba(11,11,11,.10); --accent:#2a78d6; --accent-ink:#fff;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg:#0d0d0d; --surface:#1a1a19; --ink:#ffffff; --ink2:#c3c2b7; --muted:#898781;
    --grid:#2c2c2a; --border:rgba(255,255,255,.10); --accent:#3987e5;
  }
}
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--ink); font-family:system-ui,-apple-system,"Segoe UI",sans-serif; font-size:14px; line-height:1.45; }
.app { max-width:1500px; margin:0 auto; padding:14px 18px 30px; }
.card { background:var(--surface); border:1px solid var(--border); border-radius:10px; }

header.topbar { display:flex; flex-wrap:wrap; align-items:flex-end; gap:12px; margin-bottom:12px; }
.topbar h1 { font-size:21px; margin:0; letter-spacing:-.2px; }
.topbar .sub { color:var(--ink2); font-size:12.5px; }
.topbar .actions { margin-left:auto; display:flex; gap:8px; }
button, select, input[type=text] { font:inherit; font-size:13px; color:var(--ink); background:var(--surface); border:1px solid var(--border); border-radius:7px; padding:6px 10px; }
button { cursor:pointer; }
