    <div class="kpi card"><div class="v" id="k-oper">&ndash;</div><div class="l">Operating w/ designated parking</div></div>
    <div class="kpi card"><div class="v" id="k-spaces">&ndash;</div><div class="l">Est. designated truck spaces</div></div>
    <div class="kpi card"><div class="v" id="k-field">&ndash;</div><div class="l">Field-verified</div></div>
    <div class="kpi card"><div class="v" id="k-corr">&ndash;</div><div class="l">Corridors in view</div></div>
  </div>

  <div class="filters card">
    <input type="text" id="f-search" placeholder="Search name / exit / county / notes&hellip;">
    <div class="dd" data-key="type" data-label="Type"></div>
    <div class="dd" data-key="corr" data-label="Corridor"></div>
    <div class="dd" data-key="own" data-label="Ownership"></div>
    <div class="dd" data-key="status" data-label="Status"></div>
    <div class="dd" data-key="conf" data-label="Confidence"></div>
    <div class="dd" id="dd-hidden" style="display:none"></div>
    <select id="f-sort"><option value="corr">Sort: corridor order</option><option value="name">Sort: name A&ndash;Z</option><option value="spaces">Sort: est. spaces (high first)</option></select>
    <button id="f-reset">Reset</button>
    <span class="spacer" id="f-count"></span>
  </div>

  <div class="traffic-bar card">
    <label class="switch-row" title="Show/hide the 6 active WV toll facilities"><input type="checkbox" id="sw-toll" checked> <span>Toll facilities</span></label>
    <label class="switch-row sub-toggle" title="Show former toll facilities (currently: Dunbar Toll Bridge, now free) in a separate dashed style"><input type="checkbox" id="sw-toll-former"> <span>Former tolls</span></label>
    <span class="toll-legend-mini" id="toll-legend-mini"></span>
    <label class="switch-row" title="Master switch for all traffic-intelligence layers (AADT, count stations, weigh-in-motion, citations/enforcement, crashes, live conditions)"><input type="checkbox" id="sw-traffic"> <span>Traffic Data</span></label>
  </div>

  <div id="traffic-shell" style="display:none">
    <div class="traffic-controls card" id="traffic-controls">
      <div class="traffic-layer-groups" id="traffic-layer-groups"></div>
      <div class="traffic-selectors" id="traffic-selectors">
        <div class="dd" data-key="year" data-label="Year"></div>
        <div class="dd" data-key="route" data-label="Route"></div>
        <div class="dd" data-key="county" data-label="County"></div>
        <div class="dd" data-key="dir" data-label="Direction"></div>
        <div class="dd" data-key="vclass" data-label="Vehicle class"></div>
        <div class="dd" data-key="pclass" data-label="Passenger/Commercial"></div>
        <div class="dd" data-key="citype" data-label="Citation/offense type"></div>
        <div class="dd" data-key="sev" data-label="Crash severity"></div>
        <div class="dd" data-key="agency" data-label="Enforcement agency"></div>
        <button id="tf-reset" title="Reset traffic filters (does not affect truck-parking filters)">Reset traffic filters</button>
        <button id="tf-methodology" title="Rate-calculation methodology and important definitions">Methodology</button>
      </div>
    </div>
    <div class="traffic-kpis card" id="traffic-kpis"></div>
    <div class="traffic-kpis-note">Tiles read "Not available" (never 0) when the underlying layer has no data, or when a rate's numerator/denominator coverage can't be reliably matched. See Methodology.</div>
    <div id="traffic-empty-notices"></div>
    <div class="legend card" id="traffic-legend"></div>
  </div>

  <div class="legend card" id="legend"></div>

  <div class="main">
    <div class="map-wrap card">
      <div id="map"></div>
      <div id="map-fallback">Map could not load (Leaflet CDN / internet unavailable). Filtering, details, reports and CSV export still work.</div>
    </div>
    <div class="listing card" id="listing"></div>
  </div>

  <div class="charts">
    <div class="chart card">
      <h3>Est. designated truck spaces by corridor</h3>
      <p class="note">Operating public / private / paid-reservable facilities in the current filter; analyst midpoints of published or imagery ranges.</p>
      <div id="chart-corr"></div>
    </div>
    <div class="chart card">
      <h3>Locations by category</h3>
      <p class="note">All locations in the current filter, including informal sites, candidates and resolved non-facilities.</p>
      <div id="chart-class"></div>
    </div>
  </div>

  <div class="sub" style="color:var(--muted);font-size:11.5px;">
    Source: wv-truck-parking-master.csv. Map layers: OpenStreetMap (streets), Esri World Imagery (satellite).
    Click any facility for full details and site satellite imagery. Space totals are estimates; see per-facility confidence.
    Questions or corrections? Contact Mohammad Ahmad at <a href="mailto:mohammad.ahmad@mail.wvu.edu" style="color:var(--accent)">mohammad.ahmad@mail.wvu.edu</a>.
  </div>
</div>

<div class="modal-bg" id="modal-bg">
  <div class="modal card" id="modal"></div>
</div>

<div id="report"></div>

<script>
var DATA = __DATA__;
var COLS = __COLS__;
var TSS_DATE = '__TSSDATE__';

/* ---------- toll + traffic data (tools\traffic-lib.js, inlined at build time) ---------- */
__TRAFFIC_LIB__
var TRAFFIC = __TRAFFIC__;
var TRAFFIC_META = __TRAFFIC_META__;
var CLASS_META = {
  'public':    { label:'Public facility',            light:'#2a78d6', dark:'#3987e5' },
  'private':   { label:'Private truck stop',         light:'#1baf7a', dark:'#199e70' },
  'paid':      { label:'Paid reservable lot',        light:'#eda100', dark:'#c98500' },
  'informal':  { label:'Informal / big-box',         light:'#008300', dark:'#008300' },
  'candidate': { label:'Candidate site (satellite)', light:'#4a3aa7', dark:'#9085e9' },
  'none':      { label:'No capacity / closed / ghost', light:'#898781', dark:'#898781' }
};
var CLASS_ORDER = ['public','private','paid','informal','candidate','none'];
var CORR_ORDER = ['I-64','I-77 (incl. Turnpike)','I-79','US-19 (Corridor L)','US-19 / I-79 junction'];
var isDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
function ccolor(cls) { var m = CLASS_META[cls]; return isDark ? m.dark : m.light; }

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c];
  });
}
function trunc(s, n) { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; }
function byId(id) { return document.getElementById(id); }

/* ---------- hidden facilities (viewer-side exclusions, persisted) ---------- */
var hiddenSet = {};
try {
  (JSON.parse(localStorage.getItem('wvtp-hidden') || '[]')).forEach(function (n) {
    if (DATA.some(function (r) { return r.name === n; })) { hiddenSet[n] = true; }
  });
} catch (e) {}
function saveHidden() {
  try { localStorage.setItem('wvtp-hidden', JSON.stringify(Object.keys(hiddenSet))); } catch (e) {}
}
function hiddenCount() { return Object.keys(hiddenSet).length; }
function toggleHidden(id) {
  var n = DATA[id].name;
  if (hiddenSet[n]) { delete hiddenSet[n]; } else { hiddenSet[n] = true; }
  saveHidden(); render();
}
var hiddenNamesCache = [];
function unhideAt(i) {
  delete hiddenSet[hiddenNamesCache[i]];
  saveHidden(); render();
}
function unhideAll() { hiddenSet = {}; saveHidden(); render(); }
function toggleHiddenDd() {
  var dd = byId('dd-hidden');
  var wasOpen = dd.classList.contains('open');
  closeAllDropdowns();
  if (!wasOpen) { dd.classList.add('open'); }
}
function renderHiddenDd() {
  var dd = byId('dd-hidden');
  hiddenNamesCache = Object.keys(hiddenSet).sort();
  if (!hiddenNamesCache.length) {
    dd.style.display = 'none'; dd.classList.remove('open'); dd.innerHTML = '';
    return;
  }
  var h = '<button type="button" title="Facilities you have hidden from the dashboard" onclick="event.stopPropagation();toggleHiddenDd()"><span class="t">Hidden</span><span class="n">' + hiddenNamesCache.length + '</span> &#9662;</button>';
  h += '<div class="dd-panel" onclick="event.stopPropagation()"><span class="dd-clear" onclick="unhideAll()">Unhide all</span>';
  hiddenNamesCache.forEach(function (n, i) {
    h += '<div class="hrow"><span>' + esc(n) + '</span><a href="#" onclick="unhideAt(' + i + ');return false;">Unhide</a></div>';
  });
  h += '</div>';
  dd.innerHTML = h;
  dd.style.display = '';
}

/* ---------- filters (multi-select checkbox dropdowns) ---------- */
var FACETS = [
  { key: 'type', label: 'Type' },
  { key: 'corr', label: 'Corridor' },
  { key: 'own', label: 'Ownership' },
  { key: 'status', label: 'Status' },
  { key: 'conf', label: 'Confidence' }
];
var filterState = {};
FACETS.forEach(function (f) { filterState[f.key] = {}; });
function facetActive(key) {
  return Object.keys(filterState[key]).filter(function (v) { return filterState[key][v]; });
}
function updateDdBadge(dd) {
  var n = facetActive(dd.getAttribute('data-key')).length;
  var b = dd.querySelector('button .n');
  b.style.display = n ? '' : 'none';
  b.textContent = n;
}
function closeAllDropdowns() {
  Array.prototype.slice.call(document.querySelectorAll('.filters .dd.open')).forEach(function (d) { d.classList.remove('open'); });
}
document.addEventListener('click', closeAllDropdowns);
(function buildDropdowns() {
  Array.prototype.slice.call(document.querySelectorAll('.filters .dd[data-key]')).forEach(function (dd) {
    var key = dd.getAttribute('data-key'), label = dd.getAttribute('data-label');
    var seen = {};
    DATA.forEach(function (r) { seen[r[key]] = true; });
    var vals = Object.keys(seen).sort();
    var h = '<button type="button" title="Select one or more ' + esc(label.toLowerCase()) + ' values"><span class="t">' + esc(label) + '</span><span class="n" style="display:none">0</span> &#9662;</button>';
    h += '<div class="dd-panel"><span class="dd-clear">Clear selection</span>';
    vals.forEach(function (v) {
      h += '<label><input type="checkbox" value="' + esc(v) + '"> <span>' + esc(v) + '</span></label>';
    });
    h += '</div>';
    dd.innerHTML = h;
    dd.querySelector('button').addEventListener('click', function (e) {
      e.stopPropagation();
      var wasOpen = dd.classList.contains('open');
      closeAllDropdowns();
      if (!wasOpen) { dd.classList.add('open'); }
    });
    dd.querySelector('.dd-panel').addEventListener('click', function (e) { e.stopPropagation(); });
    dd.querySelector('.dd-clear').addEventListener('click', function () {
      filterState[key] = {};
      Array.prototype.slice.call(dd.querySelectorAll('input')).forEach(function (cb) { cb.checked = false; });
      updateDdBadge(dd); render();
    });
    Array.prototype.slice.call(dd.querySelectorAll('input')).forEach(function (cb) {
      cb.addEventListener('change', function () {
        filterState[key][cb.value] = cb.checked;
        updateDdBadge(dd); render();
      });
    });
  });
})();

function filtered() {
  var q = byId('f-search').value.toLowerCase();
  return DATA.filter(function (r) {
    if (hiddenSet[r.name]) return false;
    for (var i = 0; i < FACETS.length; i++) {
      var act = facetActive(FACETS[i].key);
      if (act.length && act.indexOf(r[FACETS[i].key]) === -1) return false;
    }
    if (q) {
      var hay = (r.name + ' ' + r.raw['Milepost / exit'] + ' ' + r.raw['County'] + ' ' + r.raw['Notes'] + ' ' + r.raw['Facility type']).toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  });
}
function sorted(rows) {
  var mode = byId('f-sort').value;
  rows = rows.slice();
  if (mode === 'name') { rows.sort(function (a, b) { return a.name.localeCompare(b.name); }); }
  else if (mode === 'spaces') { rows.sort(function (a, b) { return (b.capMid || 0) - (a.capMid || 0); }); }
  else { rows.sort(function (a, b) { return a.id - b.id; }); }
  return rows;
}

/* ---------- legend ---------- */
(function () {
  var h = '<b style="color:var(--ink)">Map legend:</b>';
  CLASS_ORDER.forEach(function (c) {
    h += '<span><span class="dot" style="background:' + ccolor(c) + '"></span>' + esc(CLASS_META[c].label) + '</span>';
  });
  byId('legend').innerHTML = h;
})();

/* ---------- map ---------- */
var map = null, markerLayer = null;
if (window.L) {
  map = L.map('map').setView([38.7, -81.1], 7);
  var streets = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; OpenStreetMap contributors' });
  var satTiles = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { maxZoom: 19, attribution: 'Esri World Imagery' });
  streets.addTo(map);
  L.control.layers({ 'Streets': streets, 'Satellite': satTiles }, null, { collapsed: false, position: 'topright' }).addTo(map);
  markerLayer = L.layerGroup().addTo(map);
  var FitCtl = L.Control.extend({
    options: { position: 'topleft' },
    onAdd: function () {
      var d = L.DomUtil.create('div', 'leaflet-bar');
      d.innerHTML = '<a href="#" title="Zoom to filtered results" style="font-size:11px;width:auto;padding:0 8px;">Fit results</a>';
      d.onclick = function (e) { e.preventDefault(); fitToResults(); return false; };
      return d;
    }
  });
  map.addControl(new FitCtl());
} else {
  byId('map-fallback').style.display = 'flex';
}
function fitToResults() {
  if (!map) return;
  var pts = filtered().filter(function (r) { return r.lat != null; }).map(function (r) { return [r.lat, r.lon]; });
  if (pts.length) { map.fitBounds(pts, { padding: [30, 30], maxZoom: 13 }); }
}
function popupHtml(r) {
  var sp = trunc(r.raw['Truck spaces'], 70);
  return '<div style="min-width:220px"><b>' + esc(r.name) + '</b><br>' +
    esc(r.type) + ' &middot; ' + esc(r.own) + '<br>' +
    '<b>Spaces:</b> ' + esc(sp) + '<br>' +
    '<b>Status:</b> ' + esc(r.status) + ' &middot; ' + esc(r.conf) + '<br>' +
    '<a href="#" onclick="openDetail(' + r.id + ');return false;">Full details + satellite</a> &middot; ' +
    '<a href="#" onclick="toggleHidden(' + r.id + ');return false;" title="Exclude this facility from the map, list, counts and exports (undo via the Hidden control)">Hide</a></div>';
}
function renderMarkers(rows) {
  if (!markerLayer) return;
  markerLayer.clearLayers();
  rows.forEach(function (r) {
    if (r.lat == null) return;
    L.circleMarker([r.lat, r.lon], {
      radius: 8, color: isDark ? '#1a1a19' : '#ffffff', weight: 2,
      fillColor: ccolor(r.capClass), fillOpacity: 0.95
    }).bindPopup(popupHtml(r)).addTo(markerLayer);
  });
}

/* ---------- list ---------- */
function statusChipClass(st) {
  if (st.indexOf('Open') === 0) return 'chip st-open';
  if (st === 'Under construction' || st === 'Unverified') return 'chip st-warn';
  return 'chip';
}
function renderList(rows) {
  var h = '';
  rows.forEach(function (r) {
    h += '<div class="fcard" style="border-left-color:' + ccolor(r.capClass) + '" onclick="openDetail(' + r.id + ')">' +
      '<span class="hidebtn" onclick="event.stopPropagation();toggleHidden(' + r.id + ')" title="Hide this facility from the map, list, counts and exports (undo via the Hidden control in the filter bar)">&times; Hide</span>' +
      '<div class="nm">' + esc(r.name) + '</div>' +
      '<div class="meta">' + esc(r.corr) + ' &middot; ' + esc(trunc(r.raw['Milepost / exit'], 42)) + ' &middot; ' + esc(r.raw['County']) + ' Co.</div>' +
      '<div class="meta"><b>Spaces:</b> ' + esc(trunc(r.raw['Truck spaces'], 74)) + '</div>' +
      '<span class="' + statusChipClass(r.status) + '">' + esc(r.status) + '</span>' +
      '<span class="chip">' + esc(r.type) + '</span>' +
      '<span class="chip">' + esc(r.conf) + '</span>' +
      (r.lat != null && map ? '<div class="mini" onclick="event.stopPropagation();zoomTo(' + r.id + ')">Show on map &rarr;</div>' : '<div class="mini" style="color:var(--muted)">no coordinates</div>') +
      '</div>';
  });
  byId('listing').innerHTML = h || '<div style="padding:16px;color:var(--ink2)">No facilities match the current filters.</div>';
}
function zoomTo(id) {
  var r = DATA[id];
  if (!map || r.lat == null) return;
  map.setView([r.lat, r.lon], 15);
  markerLayer.eachLayer(function (m) {
    var ll = m.getLatLng();
    if (Math.abs(ll.lat - r.lat) < 1e-9 && Math.abs(ll.lng - r.lon) < 1e-9) { m.openPopup(); }
  });
}

/* ---------- KPIs ---------- */
function isOperating(r) { return r.capClass === 'public' || r.capClass === 'private' || r.capClass === 'paid'; }
function spacesSum(rows) {
  var s = 0, unk = 0;
  rows.forEach(function (r) {
    if (isOperating(r)) { if (r.capMid != null) { s += r.capMid; } else { unk++; } }
  });
  return { sum: s, unk: unk };
}
function renderKpis(rows) {
  var sp = spacesSum(rows);
  byId('k-shown').textContent = rows.length + ' / ' + DATA.length;
  byId('k-oper').textContent = rows.filter(isOperating).length;
  byId('k-spaces').textContent = '~' + sp.sum + (sp.unk ? '+' : '');
  byId('k-field').textContent = rows.filter(function (r) { return r.conf === 'Field-verified'; }).length;
  byId('k-corr').textContent = CORR_ORDER.filter(function (c) { return rows.some(function (r) { return r.corr === c; }); }).length;
  byId('f-count').textContent = 'Showing ' + rows.length + ' of ' + DATA.length + ' locations' + (hiddenCount() ? ' (' + hiddenCount() + ' hidden)' : '');
}

/* ---------- charts ---------- */
function barChart(el, items) {
  var max = 0;
  items.forEach(function (it) { if (it.value > max) { max = it.value; } });
  var h = '';
  items.forEach(function (it) {
    var w = max ? (it.value / max * 100) : 0;
    h += '<div class="bar-row" title="' + esc(it.label) + ': ' + it.value + '">' +
      '<div class="bar-label">' + esc(it.label) + '</div>' +
      '<div class="bar-track"><div class="bar-fill" style="width:' + w + '%;background:' + it.color + '"></div></div>' +
      '<div class="bar-val">' + it.value + '</div></div>';
  });
  el.innerHTML = h || '<div style="color:var(--ink2)">No data in the current filter.</div>';
}
function renderCharts(rows) {
  var corrItems = [];
  CORR_ORDER.forEach(function (c) {
    var s = 0;
    rows.forEach(function (r) { if (r.corr === c && isOperating(r) && r.capMid != null) { s += r.capMid; } });
    if (rows.some(function (r) { return r.corr === c; })) { corrItems.push({ label: c, value: s, color: 'var(--accent)' }); }
  });
  barChart(byId('chart-corr'), corrItems);
  var clsItems = [];
  CLASS_ORDER.forEach(function (c) {
    var n = rows.filter(function (r) { return r.capClass === c; }).length;
    if (n) { clsItems.push({ label: CLASS_META[c].label, value: n, color: ccolor(c) }); }
  });
  barChart(byId('chart-class'), clsItems);
}

/* ---------- verification info, capacity methodology, source links ---------- */
function linkifySources(s) {
  return String(s).split(/;\s*/).map(function (t) {
    t = t.trim();
    if (/^[a-z0-9][a-z0-9.-]*\.[a-z]{2,}(\/[^\s]*)?$/i.test(t)) {
      return '<a target="_blank" rel="noopener" href="https://' + esc(t) + '">' + esc(t) + '</a>';
    }
    return esc(t);
  }).join(' &middot; ');
}
function capacityBlock(r) {
  var est = r.capMid != null ? '~' + r.capMid + ' truck spaces' : 'no numeric estimate (count unavailable / unpublished)';
  return '<div class="estbox"><b>Study capacity estimate:</b> ' + est + ' &middot; counted as: ' + esc(CLASS_META[r.capClass].label) + '<br>' +
    '<span>How decided: published/field/satellite count where exact (satellite counts include occupied and open spots), otherwise analyst midpoint of the recorded figure &quot;' + esc(trunc(r.raw['Truck spaces'], 110)) + '&quot; per count source: ' + esc(r.raw['Count source'] || 'n/a') + '. Only operating public / private / paid-reservable facilities count toward the dashboard space totals; informal and candidate capacity is tracked separately and closed/ghost sites count zero.</span></div>';
}
function verifFlags(r) {
  if (r.conf === 'Field-verified') { return []; }
  var f = [];
  if (/satellite|imagery/i.test(String(r.raw['Count source'] || ''))) { f.push('space count is a satellite estimate'); }
  if (/conflict/i.test(String(r.raw['Truck spaces'] || '')) || r.conf === 'Directory-conflicting') { f.push('conflicting directory data'); }
  if (r.status === 'Unverified' || /UNVERIFIED/.test(r.name)) { f.push('existence / operation unverified'); }
  if (r.conf === 'Unresolved') { f.push('unresolved - field visit recommended'); }
  ['Lighting', 'Showers', '24/7 staff', 'Restrooms'].forEach(function (c) {
    if (/^(Unknown|Conflicting)/i.test(String(r.raw[c] || ''))) { f.push(c.toLowerCase() + ' unknown'); }
  });
  if (!f.length) { f.push('not field-verified'); }
  return f;
}
function verificationBlock(r) {
  var f = verifFlags(r);
  if (!f.length) { return '<div class="vbox ok"><b>Field-verified</b> by the study team, July 2026.</div>'; }
  return '<div class="vbox"><b>Needs field verification:</b> ' + f.map(function (x) { return '<span class="vchip">' + esc(x) + '</span>'; }).join(' ') + '</div>';
}

/* ---------- detail modal ---------- */
function tssRow(label, v) {
  if (v === '' || v == null) { return ''; }
  return '<tr><td>' + esc(label) + '</td><td>' + esc(v) + '</td></tr>';
}
function tssBlock(r) {
  var t = r.tss;
  if (!t) {
    return '<div class="vbox">Not listed on truckstopsandservices.com &mdash; WV truck stop, rest area, and drop-yard categories checked' + (TSS_DATE ? ' ' + esc(TSS_DATE) : '') + '.</div>';
  }
  var spots = t.ParkingSpots;
  if (t.ReservedSpots && t.ReservedSpots !== '0') { spots += ' (' + t.ReservedSpots + ' reserved)'; }
  if (t.PaidSpots && t.PaidSpots !== '0') { spots += ' (' + t.PaidSpots + ' paid)'; }
  var h = '<div class="estbox"><b>As published by TruckStopsAndServices.com</b> &mdash; shown verbatim for source comparison; the study estimate on the Study data tab may differ.</div>';
  h += '<table>';
  h += tssRow('Listed as', t.TssName + ' (' + t.Category + ')');
  h += tssRow('Highway / exit', (t.Highway || '') + (t.Exit ? ' exit ' + t.Exit : ''));
  h += tssRow('Address', [t.StreetAddress, t.City, t.State, t.PostalCode].filter(function (x) { return x; }).join(', '));
  h += tssRow('Phone', t.Phone);
  h += tssRow('Hours', t.Hours);
  h += tssRow('Parking spots', spots);
  h += tssRow('Fuel lanes', t.FuelLanes);
  h += tssRow('Showers', t.Showers);
  h += tssRow('Truck service bays', t.ServiceBays);
  h += tssRow('Rating', t.RatingAvg ? t.RatingAvg + ' / 5 (' + t.RatingCount + ' ratings)' : '');
  h += tssRow('GPS (per TSS)', t.Latitude ? t.Latitude + ', ' + t.Longitude : '');
  h += tssRow('Amenities', t.Amenities);
  h += tssRow('Payment methods', t.Payments);
  h += tssRow('Customer feedback', t.Feedback);
  h += '</table>';
  h += '<div class="links" style="margin-top:8px"><a target="_blank" rel="noopener" href="' + esc(t.Url) + '">View live listing on truckstopsandservices.com</a></div>';
  h += '<div class="tssnote">Fetched ' + esc(t.FetchedDate) + ' by tools\\fetch-tss.ps1 (cached in tss-cache\\).' + (t.MatchNote ? ' Match: ' + esc(t.MatchNote) : '') + '</div>';
  return h;
}
function showTab(n) {
  [0, 1].forEach(function (i) {
    byId('tabpane' + i).style.display = (i === n) ? '' : 'none';
    byId('tabbtn' + i).className = (i === n) ? 'tab active' : 'tab';
  });
}
function openDetail(id) {
  var r = DATA[id];
  var h = '<button class="x" onclick="closeDetail()" title="Close">&times;</button>' +
    '<h2>' + esc(r.name) + '</h2>' +
    '<div class="sub">' + esc(r.corr) + ' &middot; ' + esc(r.raw['Milepost / exit']) + ' &middot; ' + esc(r.raw['County']) + ' County &middot; ' + esc(CLASS_META[r.capClass].label) + '</div>';
  var links = '';
  if (r.lat != null) {
    links += '<a target="_blank" rel="noopener" href="https://www.google.com/maps?q=' + r.lat + ',' + r.lon + '">Open in Google Maps</a>' +
      '<a target="_blank" rel="noopener" href="https://www.google.com/maps/@' + r.lat + ',' + r.lon + ',900m/data=!3m1!1e3">Google Maps satellite</a>' +
      (map ? '<a href="#" onclick="closeDetail();zoomTo(' + r.id + ');return false;">Show on dashboard map</a>' : '');
  }
  links += '<a href="#" onclick="closeDetail();toggleHidden(' + r.id + ');return false;" title="Exclude this facility from the map, list, counts and exports (undo via the Hidden control)">Hide from dashboard</a>';
  h += '<div class="links">' + links + '</div>';
  h += '<div class="tabbar">' +
    '<button id="tabbtn0" class="tab active" onclick="showTab(0)">Study data</button>' +
    '<button id="tabbtn1" class="tab" onclick="showTab(1)">TruckStopsAndServices.com</button>' +
    '</div>';
  var s = capacityBlock(r);
  s += verificationBlock(r);
  if (r.sat) { s += '<img class="sat" src="satellite/' + esc(r.sat) + '" alt="Satellite image of ' + esc(r.name) + '">'; }
  s += '<table>';
  COLS.forEach(function (c) {
    var v = r.raw[c];
    if (v === '' || v == null) { return; }
    var cell = (c === 'Sources' || c === 'Count source') ? linkifySources(v) : esc(v);
    s += '<tr><td>' + esc(c) + '</td><td>' + cell + '</td></tr>';
  });
  s += '</table>';
  h += '<div id="tabpane0" class="tabpane">' + s + '</div>';
  h += '<div id="tabpane1" class="tabpane" style="display:none">' + tssBlock(r) + '</div>';
  byId('modal').innerHTML = h;
  byId('modal-bg').style.display = 'flex';
}
function closeDetail() { byId('modal-bg').style.display = 'none'; }
byId('modal-bg').addEventListener('click', function (e) { if (e.target === this) { closeDetail(); } });
document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { closeDetail(); } });

/* ---------- report generation ---------- */
function activeFilterText() {
  var parts = [];
  FACETS.forEach(function (f) {
    var act = facetActive(f.key);
    if (act.length) { parts.push(f.label + ': ' + act.join(' / ')); }
  });
  var q = byId('f-search').value;
  if (q) { parts.push('search: "' + q + '"'); }
  if (hiddenCount()) { parts.push(hiddenCount() + ' facilit' + (hiddenCount() === 1 ? 'y' : 'ies') + ' hidden by viewer'); }
  return parts.length ? parts.join(' | ') : 'none (full inventory)';
}
function buildReport() {
  var rows = sorted(filtered());
  var sp = spacesSum(rows);
  var h = '<h1>WV Truck Parking Study &mdash; Report</h1>' +
    '<div class="sub">Semi-truck parking on I-64, I-77 (WV Turnpike), I-79 and US-19 (Corridor L) &middot; generated ' + esc(new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })) + ' from wv-truck-parking-master.csv<br><b>Filters applied:</b> ' + esc(activeFilterText()) + '</div>' +
    '<h2>Summary</h2>' +
    '<table><tr><th>Locations in report</th><th>Operating w/ designated parking</th><th>Est. designated truck spaces</th><th>Field-verified</th></tr>' +
    '<tr><td>' + rows.length + ' of ' + DATA.length + '</td><td>' + rows.filter(isOperating).length + '</td><td>~' + sp.sum + (sp.unk ? ' (+' + sp.unk + ' facilities without published counts)' : '') + '</td><td>' + rows.filter(function (r) { return r.conf === 'Field-verified'; }).length + '</td></tr></table>';

  h += '<h2>Breakdown by corridor</h2><table><tr><th>Corridor</th><th>Locations</th><th>Est. designated spaces</th></tr>';
  CORR_ORDER.forEach(function (c) {
    var cr = rows.filter(function (r) { return r.corr === c; });
    if (!cr.length) return;
    var s = spacesSum(cr);
    h += '<tr><td>' + esc(c) + '</td><td>' + cr.length + '</td><td>~' + s.sum + (s.unk ? '+' : '') + '</td></tr>';
  });
  h += '</table>';

  h += '<h2>Facility table</h2><table><tr><th>Facility</th><th>Milepost / exit</th><th>Access</th><th>Type</th><th>Ownership</th><th>Truck spaces</th><th>Status</th><th>Confidence</th></tr>';
  rows.forEach(function (r) {
    h += '<tr><td><b>' + esc(r.name) + '</b></td><td>' + esc(trunc(r.raw['Milepost / exit'], 36)) + '</td><td>' + esc(trunc(r.raw['Direction access'], 26)) + '</td><td>' + esc(r.type) + '</td><td>' + esc(r.own) + '</td><td>' + esc(trunc(r.raw['Truck spaces'], 60)) + '</td><td>' + esc(r.status) + '</td><td>' + esc(r.conf) + '</td></tr>';
  });
  h += '</table>';

  h += '<h2>Facility details</h2>';
  rows.forEach(function (r) {
    h += '<div class="rcard">' +
      (r.sat ? '<img src="satellite/' + esc(r.sat) + '" alt="">' : '') +
      '<h3>' + esc(r.name) + '</h3>' +
      '<div class="m">' + esc(r.corr) + ' &middot; ' + esc(r.raw['Milepost / exit']) + ' &middot; ' + esc(r.raw['County']) + ' County' + (r.lat != null ? ' &middot; ' + r.lat + ', ' + r.lon : '') + '</div>' +
      '<p><b>Type:</b> ' + esc(r.raw['Facility type']) + ' &middot; <b>Ownership:</b> ' + esc(r.raw['Ownership']) + '</p>' +
      '<p><b>Truck spaces:</b> ' + esc(r.raw['Truck spaces']) + ' <i>(' + esc(r.raw['Count source']) + ')</i></p>' +
      '<p><b>Status:</b> ' + esc(r.raw['Status']) + ' &middot; <b>Cost:</b> ' + esc(r.raw['Cost / reservation']) + '</p>' +
      '<p><b>Amenities:</b> restrooms: ' + esc(r.raw['Restrooms']) + ' &middot; showers: ' + esc(r.raw['Showers']) + ' &middot; 24/7 staff: ' + esc(r.raw['24/7 staff']) + ' &middot; lighting: ' + esc(r.raw['Lighting']) + ' &middot; fuel: ' + esc(r.raw['Fuel / diesel']) + '</p>' +
      '<p><b>Study estimate:</b> ' + (r.capMid != null ? '~' + r.capMid + ' spaces' : 'no numeric estimate') + ' (' + esc(CLASS_META[r.capClass].label) + ')' + (verifFlags(r).length ? ' &middot; <b>Verify in field:</b> ' + esc(verifFlags(r).join('; ')) : ' &middot; field-verified July 2026') + '</p>' +
      (r.raw['Notes'] ? '<p><b>Notes:</b> ' + esc(r.raw['Notes']) + '</p>' : '') +
      (r.raw['Sources'] ? '<p><b>Sources:</b> ' + esc(r.raw['Sources']) + '</p>' : '') +
      '</div>';
  });
  byId('report').innerHTML = h;
}
byId('btn-report').addEventListener('click', function () {
  buildReport();
  setTimeout(function () { window.print(); }, 150);
});

/* ---------- CSV export ---------- */
function csvCell(v) {
  v = String(v == null ? '' : v);
  return /[",\r\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
}
byId('btn-csv').addEventListener('click', function () {
  var rows = sorted(filtered());
  var lines = [COLS.map(csvCell).join(',')];
  rows.forEach(function (r) { lines.push(COLS.map(function (c) { return csvCell(r.raw[c]); }).join(',')); });
  var blob = new Blob(['﻿' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'wv-truck-parking-filtered.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(a.href);
});

/* ---------- render loop ---------- */
function render() {
